for mode in "--w 1000" "--w 1440" "--phone"; do for i in 0 1 2 3 4 5 6 7 8; do echo "svc tab $i $mode"; PRE="S.svc360.sel='svc_search';S.v.s360d=$i;render()" node spacescan_pre.js out_svc360 $mode --only svc_360 2>&1 | tail -12; done; for i in 0 1 2 3 4; do echo "tbm tab $i $mode"; PRE="S.v.tbmv=$i;render()" node spacescan_pre.js out_svc360 $mode --only tbm_model 2>&1|tail -12; done; done
